// Unbekannte Unterseiten der Länderfassungen (/de/…, /at/…, /ch/…): 404 INNERHALB des Länder-
// Root-Layouts, damit <html lang> (de-DE/de-AT/de-CH) und die Land-Links der 404-Seite stimmen
// (not-found.js daneben). Ohne diese Route zeigte Next.js für tiefere Pfade die globale 404
// (lang="de", gemeinsame Links). Explizite Seiten haben Vorrang; diese Route rendert nie Inhalt.
// Ausnahme im Register-Abgleich von scripts/landfassungen.mjs (keine Seite, nur 404).
import { notFound } from "next/navigation";

export const dynamic = "force-dynamic";

export default async function UnbekannteLandSeite() {
  notFound();
}

// Gemeinsamer Rahmen der Root-Layouts (Welle 2, Länderrouting).
//
// Die Website hat drei Root-Layouts, damit <html lang> serverseitig stimmt:
//   src/app/(stamm)/layout.js          lang="de"     – gemeinsame Seiten, Portal, Login, Token-Strecken
//   src/app/(laender)/[land]/layout.js lang="de-DE" | "de-AT" | "de-CH" – Länderfassungen derselben Seiten
//   src/app/(en)/layout.js             lang="en"     – englische Fassungen derselben Seiten (/en, /en/at …)
// Land (Ländermodell) und Sprache (Sprachmodell) gehen als Kontext an alle Client-Komponenten
// (LandProvider, SpracheProvider).
// plus src/app/global-not-found.js für Pfade außerhalb aller Layouts.
// Ein Wechsel zwischen Root-Layouts lädt die Seite vollständig neu (Next.js) – gewollt.
//
// Alles, was vorher im einzigen Root-Layout stand (Schriften, Metadaten, JSON-LD,
// noindex außerhalb der Produktion, Sprunglink, LayoutWrapper, GA), steht jetzt hier.

import GoogleAnalytics from "@/components/Statistik/GoogleAnalytics";
import { Inter, Manrope } from "next/font/google";
import LayoutWrapper from "@/components/Reusable/LayoutWrapper";
import { GESELLSCHAFT, INDEXIERBAR, SITE } from "@/data/site";
import JsonLd from "@/components/JsonLd";
import { LandProvider } from "@/components/Land/LandKontext";
import { SpracheProvider } from "@/components/Sprache/SpracheKontext";
import { LAND_AUS_PFAD } from "@/lib/land/laender";

export { LAND_AUS_PFAD };

// Zwei Schriften wie auf oekovolt.de: Inter für Fließtext, Manrope für
// Überschriften. next/font hostet beide selbst (keine Verbindung zu Google).
const inter = Inter({
  subsets: ["latin", "latin-ext"],
  display: "swap",
  variable: "--font-inter",
  fallback: ["system-ui", "Segoe UI", "Arial", "sans-serif"],
});

const manrope = Manrope({
  subsets: ["latin", "latin-ext"],
  weight: ["500", "600", "700", "800"],
  display: "swap",
  variable: "--font-manrope",
  fallback: ["system-ui", "Segoe UI", "Arial", "sans-serif"],
});

const BASE_URL = SITE.url;

const siteSchema = (inLanguage) => ({
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "Organization",
      "@id": `${BASE_URL}/#organization`,
      name: "ÖkoInvest",
      legalName: GESELLSCHAFT.name,
      alternateName: ["Oekoinvest", "ÖkoInvest GmbH", "ÖKOINVEST"],
      url: BASE_URL,
      logo: { "@type": "ImageObject", "@id": `${BASE_URL}/#logo`, url: `${BASE_URL}/icon-512.png`, width: 512, height: 512, caption: "ÖkoInvest" },
      image: { "@id": `${BASE_URL}/#logo` },
      description: SITE.kurz,
      slogan: SITE.claim,
      foundingDate: "2020-09-10",
      address: {
 * <html>/<body> mit allem, was jede Seite braucht.
 * @param {{ lang: string, sprache?: "de"|"en", land?: "DE"|"AT"|"CH"|null|"pfad", children: any }} p
 *   land = LAND_AUS_PFAD: Land im Browser aus dem Pfad (englische Seiten, ein Root-Layout für /en/**)
 */
export default function Wurzel({ lang, sprache = "de", land = null, children }) {
  return (
    <html lang={lang} dir="ltr" className={`${inter.variable} ${manrope.variable}`}>
      <body className="bg-white text-ink-900">
        {/* Paket I: Außerhalb der Produktion zusätzlich ein festes noindex (React
            hebt <meta> in den <head>). Seiten mit eigenem robots-Eintrag
            (index: true) überschreiben das metadata-Feld; bei zwei
            robots-Angaben gilt für Suchmaschinen die strengere. */}
        {!INDEXIERBAR && <meta name="robots" content="noindex, nofollow" />}
        <a href="#main-content" className="sr-only focus:not-sr-only focus:absolute focus:top-2 focus:left-2 focus:z-[9999] focus:px-4 focus:py-2 focus:bg-ov-600 focus:text-white focus:rounded">
          {(sprache === "en" ? TEXTE.en : TEXTE.de).sprung}
        </a>
        <JsonLd daten={siteSchema(lang)} />
        <SpracheProvider sprache={sprache}>
          <LandProvider land={land}>
            <LayoutWrapper>{children}</LayoutWrapper>
          </LandProvider>
        </SpracheProvider>
        <GoogleAnalytics />
      </body>
    </html>
  );
}
// Gemeinsamer Inhalt der 404-Seiten (je Root-Layout eine not-found.js). Links bleiben über die
// Link-Komponente im Land der Seite (Ländermodell).
import Link from "@/components/Land/Link";
import { ArrowRight, BookOpen, Calculator, Home, LayoutGrid, MapPinned } from "lucide-react";
import Button from "@/components/ui/Button";
import { NichtGefunden } from "@/components/illustrationen";

const ZIELE = [
  { titel: "Flächencheck", text: "Eignung Ihrer Fläche prüfen", href: "/flaechencheck", icon: MapPinned },
  { titel: "Projektbörse", text: "PV-Projekte in allen Phasen", href: "/projektboerse", icon: LayoutGrid },
  { titel: "Rechner", text: "Pacht, Agri-PV, Solarpark, Reststrom", href: "/rechner", icon: Calculator },
  { titel: "Ratgeber", text: "Pacht, Genehmigung, Investment", href: "/ratgeber", icon: BookOpen },
];

// Sprachmodell: englische Texte für die 404 unter /en (src/app/(en)/en/not-found.js)
const TEXTE = {
  de: { titel: "Diese Fläche ist noch nicht erschlossen.", lead: "Die gesuchte Seite existiert nicht oder wurde verschoben. Diese Wege führen weiter:", start: "Zur Startseite", ziele: ZIELE },
  en: {
    titel: "This site has not been developed yet.",
    lead: "The page you are looking for does not exist or has moved. These routes lead on:",
    start: "To the home page",
    ziele: [
      { ...ZIELE[0], titel: "Land check", text: "Check whether your land is suitable" },
      { ...ZIELE[1], titel: "Project exchange", text: "PV projects in all phases" },
      { ...ZIELE[2], titel: "Calculators", text: "Lease, agrivoltaics, solar park, residual power" },
      { ...ZIELE[3], titel: "Guides", text: "Lease, permits, investment" },
    ],
  },
};

/** Inhalt der 404-Seite (gemeinsam, Länderfassungen, englisch, globale 404). */
export default function NichtGefundenSeite({ sprache = "de" }) {
  const t = TEXTE[sprache] || TEXTE.de;
  return (
    <section className="ov-noise relative isolate overflow-hidden bg-navy-950 text-white">
      <div aria-hidden="true" className="ov-grid-bg absolute inset-0 -z-10" />
      <div aria-hidden="true" className="absolute left-1/2 top-1/3 -z-10 h-[520px] w-[520px] -translate-x-1/2 rounded-full bg-ov-500/25 blur-[140px]" />
      <div className="ov-container flex min-h-[70vh] flex-col items-center justify-center py-20 text-center">
        <div aria-hidden="true" className="ov-hero-in mb-2 w-40 motion-safe:animate-ov-float md:w-48">
          <NichtGefunden ton="dunkel" animiert />
        </div>
        <p aria-hidden="true" className="ov-hero-in select-none font-display text-[clamp(7rem,5rem+10vw,14rem)] font-extrabold leading-none tracking-tighter">
          <span className="ov-text-gradient-light">404</span>
        </p>
        <h1 className="ov-h2 ov-hero-in mt-4" style={{ "--ov-delay": "100ms" }}>
          {t.titel}
        </h1>
        <p className="ov-lead ov-hero-in mx-auto mt-5 max-w-xl text-white/75" style={{ "--ov-delay": "180ms" }}>
          {t.lead}
        </p>
        <ul className="ov-hero-in mt-10 grid w-full max-w-4xl gap-3 sm:grid-cols-2 lg:grid-cols-4" style={{ "--ov-delay": "260ms" }}>
          {t.ziele.map((z) => (
            <li key={z.href}>
              <Link href={z.href} className="group ov-glass ov-press flex h-full flex-col items-start rounded-3xl p-5 text-left transition-colors hover:bg-white/15">
                <z.icon aria-hidden="true" className="h-6 w-6 text-ov-300" />
                <span className="mt-4 font-display text-[17px] font-bold">{z.titel}</span>
                <span className="mt-1 text-[14px] text-white/75">{z.text}</span>
                <ArrowRight aria-hidden="true" className="mt-4 h-4 w-4 text-white/50 transition-transform group-hover:translate-x-1 group-hover:text-white" />
              </Link>
            </li>
          ))}
        </ul>
        <div className="ov-hero-in mt-10" style={{ "--ov-delay": "320ms" }}>
          <Button href="/" size="lg" icon={Home}>
            {t.start}
          </Button>
        </div>
      </div>
    </section>
  );
}
// 404 in den Länderfassungen (/de, /at, /ch …). Linkziele bleiben im Land der Seite
// (Link-Komponente src/components/Land/Link.js liest das Land aus dem Root-Layout).
import NichtGefundenSeite from "@/components/Wurzel/NichtGefundenSeite";

export const metadata = {
  title: "Seite nicht gefunden | ÖkoInvest",
  robots: { index: false, follow: true },
