  const zeile = sprachCookieZeile(code, { https: typeof location !== "undefined" && location.protocol === "https:" });
  if (zeile) document.cookie = zeile;
}

export function useSpracheWaehlen() {
  return useCallback((code) => spracheWaehlen(code), []);
}
