 * Texte in der Sprache mit Rückfall auf Deutsch.
 * @template T
 * @param {{ de: T, en?: any }} texte
 * @param {string|null} sprache "de" | "en"
 * @returns {T}
 */
export function uebersetze(texte, sprache) {
  if (!texte || !Object.hasOwn(texte, "de")) throw new Error("uebersetze: Eintrag „de“ fehlt");
  if (sprache !== "en" || !Object.hasOwn(texte, "en")) return texte.de;
  return zusammenfuehren(texte.de, texte.en);
}

/**
 * Länderinhalt UND Sprache.
 * @param {{ de: { gemeinsam: any, DE?: any, AT?: any, CH?: any }, en?: { gemeinsam?: any, DE?: any, AT?: any, CH?: any } }} inhalte
 * @param {string|null} land
 * @param {string|null} sprache
 */
export function inhaltFuerSprache(inhalte, land, sprache) {
  const de = inhaltFuer(inhalte.de, land);
  if (sprache !== "en" || !inhalte.en) return de;
  const l = landCode(land);
  const eigenesLand = l && Object.hasOwn(inhalte.de, l) && inhalte.de[l] !== undefined;
  if (eigenesLand) {
    if (!Object.hasOwn(inhalte.en, l)) return de; // Länderinhalt noch nicht übersetzt → deutsch
    // Schlüssel, die das Land selbst setzt, bekommen NUR die englische Länderfassung – sonst würden
    // Werte der englischen gemeinsamen Fassung (z. B. eine Zahl für Deutschland) den Länderwert überschreiben.
    const deLand = inhalte.de[l];
    const enGemeinsam =
      istObjekt(deLand) && istObjekt(inhalte.en.gemeinsam)
        ? Object.fromEntries(Object.entries(inhalte.en.gemeinsam).filter(([k]) => !Object.hasOwn(deLand, k)))
        : inhalte.en.gemeinsam;
    return zusammenfuehren(de, zusammenfuehren(enGemeinsam ?? {}, inhalte.en[l]));
  }
  return zusammenfuehren(de, inhalte.en.gemeinsam);
}

/**
 * Texte, die im englischen Wörterbuch fehlen (für Tests der Übersetzer-Teams):
 * Jeder String im deutschen Baum braucht einen englischen Wert an derselben Stelle – ausgenommen
 * technische Felder (href, id, slug, bild, src, icon, ton, typ) und Pfade/Adressen ("/…", "#…", "http…").
 * @returns {string[]} Pfade wie "liste.2.text"
 */
const TECHNISCHE_FELDER = new Set(["href", "id", "slug", "bild", "src", "icon", "ton", "typ"]);

export function fehlendeTexte(de, en, pfad = "") {
  if (TECHNISCHE_FELDER.has(String(pfad).split(".").pop())) return [];
  if (typeof de === "string") return /^(\/|#|https?:)/.test(de) || (en !== undefined && en !== null) ? []: [pfad || "(wurzel)"];
  if (typeof en === "function" || typeof de !== "object" || de === null || de.$$typeof) return [];
  if (typeof en === "string" || (en && en.$$typeof)) return [];
  const e = en ?? (Array.isArray(de) ? [] : {});
  const fehlt = [];
  for (const k of Object.keys(de)) fehlt.push(...fehlendeTexte(de[k], e[k], pfad ? `${pfad}.${k}` : String(k)));
  return fehlt;
}

// src/lib/land/seite.js – Land einer Seite auf dem Server (nutzt react/cache und next/navigation)
//
// Getrennt von index.js, damit node:test, next.config.mjs, Middleware und Client-Komponenten die
// reine Länderlogik ohne Server-Funktionen laden können.
//
// Jede öffentliche Seite (src/app/(stamm)/…/page.js) ist zugleich ihre Länderfassung: Die Route
// src/app/(laender)/[land]/…/page.js exportiert genau diese Seite weiter, Next.js reicht dabei
// params.land ("de" | "at" | "ch") durch. Die Seite ruft am Anfang
//
//   const land = await seitenLand(params);          // "DE" | "AT" | "CH" | null (= gemeinsam)
//
// und exportiert ihre Metadaten über
//
//   export const generateMetadata = seitenMetadata("/rechner/pacht", metadata);
//
// Tiefer liegende Server-Komponenten (z. B. RechnerSeite) lesen das Land danach mit
// landDerAnfrage() – ohne es durchreichen zu müssen. Client-Komponenten nutzen useLand()
// (src/components/Land/useLand.js), das Land kommt dort aus dem Root-Layout.

import { cache } from "react";
import { notFound } from "next/navigation";
import { landAusPraefix } from "./laender.js";
import { alternates, fassungIndexierbar, ogLocale } from "./pfad.js";
import { spracheOder } from "../sprache/sprachen.js";
import { uebersetze } from "../sprache/woerterbuch.js";

/** Speicher je Anfrage (React cache): Land und Sprache der gerade gerenderten Seite. */
const anfrage = cache(() => ({ land: null, sprache: "de", gesetzt: false }));

/**
 * Sprache aus den Routenparametern: Die englischen Routen (src/app/(en)/en/…, erzeugt mit
 * scripts/landfassungen.mjs) reichen params.sprache = "en" an dieselbe Seitenkomponente durch
 * (src/lib/sprache/route.js). Ohne Angabe: Deutsch.
 */
export const spracheAusParams = (p) => spracheOder(p?.sprache);

/**
 * Land aus den Routenparametern. Ohne params.land: gemeinsame Seite (null).
 * Unbekanntes Präfix → 404. Merkt sich das Land für landDerAnfrage().
 * @param {Promise<object>|object} params
 * @returns {Promise<"DE"|"AT"|"CH"|null>}
 */
export async function seitenLand(params) {
  const p = (await params) || {};
  let land = null;
  if (p.land !== undefined) {
    land = landAusPraefix(p.land);
    if (!land) notFound();
  }
  const a = anfrage();
  a.land = land;
  a.sprache = spracheAusParams(p);
  a.gesetzt = true;
  return land;
}

/**
 * Land der aktuellen Seite für Server-Komponenten unterhalb der Seite.
 * Nur gültig, nachdem die Seite seitenLand(params) aufgerufen hat (sonst null = gemeinsam).
 */
export function landDerAnfrage() {
  return anfrage().land;
}

/**
 * Sprache der aktuellen Seite ("de" | "en") für Server-Komponenten unterhalb der Seite.
 * Nur gültig, nachdem die Seite seitenLand(params) aufgerufen hat (sonst "de").
 */
export function spracheDerAnfrage() {
  return anfrage().sprache;
}

/**
 * generateMetadata für eine öffentliche Seite (gemeinsam, Länderfassung, englische Fassung):
 * übernimmt die Basis-Metadaten und setzt canonical, hreflang, og:url und og:locale.
 * Noindex bekommen Länderfassungen ohne eigenen Länderinhalt (Register src/lib/land/seiten.js)
 * und englische Fassungen, die noch nicht übersetzt sind (src/lib/sprache/seiten.js).
 * @param {string | ((p: object) => string)} schluessel Pfad ohne Präfix (bei [slug]-Routen aus params)
 * @param {object | ((land: string|null, p: object) => object|Promise<object>)} basis  p.sprache = "de" | "en"
 * @param {{ en?: object | ((de: object) => object) }} [woerterbuch] englische Metadaten (title,
 *   description, openGraph.title …), tief über die deutschen gelegt (uebersetze()).
 */
export function seitenMetadata(schluessel, basis, woerterbuch = {}) {
  return async function generateMetadata({ params }) {
    const p = (await params) || {};
    const land = p.land !== undefined ? landAusPraefix(p.land) : null;
    const sprache = spracheAusParams(p);
    const konkret = typeof schluessel === "function" ? schluessel(p) : schluessel;
    const roh = (typeof basis === "function" ? await basis(land, p) : basis) || {};
    const b = sprache === "en" && woerterbuch?.en ? uebersetze({ de: roh, en: woerterbuch.en }, "en") : roh;
    const a = alternates(konkret, land, { languages: b.alternates?.languages, sprache });
    const index = land || sprache !== "de" ? fassungIndexierbar(konkret, land, sprache) : null;
    const locale = land || sprache !== "de" ? { locale: ogLocale(land, sprache) } : {};
    return {
      ...b,
      alternates: { ...(b.alternates || {}), ...a, ...(a.languages ? {} : { languages: undefined }) },
      ...(b.openGraph ? { openGraph: { ...b.openGraph, url: a.canonical, ...locale } } : {}),
      ...(index === false ? { robots: { index: false, follow: true } } : {}),
    };
  };
}
// src/lib/land/laender.js – die drei Länderzonen (Welle 2, Länderrouting, Masterplan Abschnitt 4)
//
// Einzige Quelle für Ländercode, URL-Präfix, Sprache (BCP 47 für <html lang> und hreflang),
// og:locale und Währung. Namen und länderbezogene Kontaktangaben kommen aus src/data/site.js
// (LAENDER_ANGABEN), die Währung aus dem Faktenregister (B1, src/lib/fakten/waehrung.js).
//
// Relative Importe mit Dateiendung: Das Modul wird auch von next.config.mjs (über umzug.js)
// und von node:test ohne Alias-Auflösung geladen.

import { LAENDER_ANGABEN } from "../../data/site.js";
import { waehrungFuer } from "../fakten/waehrung.js";

/** Reihenfolge = Anzeige im Länderwechsler. DE zuerst (größter Markt, x-default der Länderzonen). */
export const LAND_CODES = Object.freeze(["DE", "AT", "CH"]);

const BASIS = {
  DE: { praefix: "de", lang: "de-DE", ogLocale: "de_DE" },
  AT: { praefix: "at", lang: "de-AT", ogLocale: "de_AT" },
  CH: { praefix: "ch", lang: "de-CH", ogLocale: "de_CH" },
};

export const LAENDER = Object.freeze(
  Object.fromEntries(
    LAND_CODES.map((code) => [
      code,
      Object.freeze({ code, ...BASIS[code], ...LAENDER_ANGABEN[code], waehrung: waehrungFuer(code), einstieg: `/${BASIS[code].praefix}` }),
    ]),
  ),
);

/** "de" | "DE" | " at " → "DE" | "AT"; alles andere → null */
export function landCode(wert) {
  const s = typeof wert === "string" ? wert.trim().toUpperCase() : "";
  return LAND_CODES.includes(s) ? s : null;
}

/** URL-Präfix ("de") → Ländercode ("DE"); nur exakt kleingeschriebene Präfixe sind gültig. */
export function landAusPraefix(praefix) {
  if (typeof praefix !== "string") return null;
  return LAND_CODES.find((c) => BASIS[c].praefix === praefix) || null;
}

/** Länderinfo; unbekannt → null */
export const landInfo = (wert) => LAENDER[landCode(wert)] || null;

/** Einstiegsseite eines Landes ("/de"); unbekannt → null */
export const einstiegPfad = (wert) => landInfo(wert)?.einstieg || null;

/** Präfix-Muster am Pfadanfang: "/de", "/de/…", "/at…" */
export const PRAEFIX_MUSTER = /^\/(de|at|ch)(?=\/|$|\?|#)/;

/** Wert für LandProvider: Land im Browser aus dem Pfad lesen (/en/at/… → AT; englische Seiten). */
export const LAND_AUS_PFAD = "pfad";

